content:
{
  "is_open_solicitation": true,
  "buyer": "Achievement First",
  "title": "Request for Proposals: Website Redesign & Ecosystem Development",
  "due_date": "2026-11-02",
  "fit_score": 25,
  "why_fit": [
    "Hand-coded, mobile-first websites with strong SEO and performance focus",
    "Managed hosting with daily backups, SSL, and monitoring",
    "Experience with structured data and local SEO",
    "Flutter mobile app development capability",
    "Massachusetts-based digital agency"
  ],
  "gaps": [
    "No enterprise multi-site CMS experience (41 school sites + regional hubs)",
    "No demonstrated large-scale content migration across 40+ sites",
    "Lacks integration experience with SchoolMint, HubSpot, Greenhouse, Salesforce, Fundraise Up, Okta",
    "No WCAG 2.2 AA compliance verification track record",
    "No multilingual (English/Spanish) architecture experience",
    "Insufficient case studies for enterprise/federated CMS implementations",
    "Team size likely inadequate for project scope and timeline",
    "May not meet insurance requirements (Cyber Liability, E&O)"
  ],
  "requirements": [
    "Proposal in PDF format via email to Jacqui Alessi by November 2, 2026",
    "Seven-section proposal format: Executive Summary, Agency Profile & Team, Case Studies & References, Technical Solution, Work Plan & Schedule, Pricing & TCO, Terms & Compliance",
    "Three relevant case studies with measurable outcomes, live URLs, client references",
    "Demonstrated multi-tier ecosystem deployment capability",
    "WCAG 2.2 AA compliance approach",
    "Content migration plan for all network, regional, and school pages",
    "Transparent technology dependencies and full IP ownership transfer",
    "Insurance verification: General Liability, Cyber Liability, Errors & Omissions",
    "Proposal valid for 90 days post-submission"
  ],
  "evidence": [
    {
      "claim": "RFP seeks vendor for unified multi-tier web ecosystem",
      "quote": "Achievement First is seeking an experienced digital agency to architect and build a unified, scalable digital ecosystem."
    },
    {
      "claim": "Project includes 41 school sites under central governance",
      "quote": "The solution will comprise a main network website, regional hubs, and 41 distinct school-specific websites under a central governance model."
    },
    {
      "claim": "Proposal submission deadline is November 2, 2026",
      "quote": "Proposals must be submitted in PDF format via email no later than November 2, 2026 to Jacqui Alessi."
    },
    {
      "claim": "Requires WCAG 2.2 AA compliance and multilingual support",
      "quote": "Full adherence to WCAG 2.2 Level AA standards verified via automated tools and manual screen-reader/keyboard testing."
    },
    {
      "claim": "Must integrate with SchoolMint, HubSpot, Greenhouse, Salesforce, Fundraise Up",
      "quote": "Current and anticipated integrations include SchoolMint/HubSpot (Enrollment CRM), Greenhouse (Careers), Salesforce & Fundraise Up (Fundraising)."
    },
    {
      "claim": "Vendor must provide three relevant case studies",
      "quote": "Three relevant case studies demonstrating multi-site, federated, or enterprise CMS implementations."
    },
    {
      "claim": "Insurance requirements include Cyber Liability and E&O",
      "quote": "Adequate insurance coverage (General Liability, Cyber Liability, Errors & Omissions)."
    }
  ]
}
